  ["w_to,nw_to,sw_to"] = function(s, t)
    if fn_check_compass(t) then
      return
    end
    s.depth = s.depth + 1
    if s.depth > 8 then
      s.depth = 6 + fn_rnd(3)
    end
    fn_forest_scenery(s)
    me():need_scene(true)
    p("Ты идешь некоторое время на ", (_('@' .. t).word), ".")
    if s.depth > 7 and fn_rnd(100) < 30 then
      p("^Ты можешь идти так целую вечность...")
    end
