      p("Голем последовал за тобой. Его шаги гулко отражались от изломанных стен и сводчатого потолка.")
      pn("Через некоторое время коридор кончился и вы вошли в большой зал.")
      pn("Зал был огромен! В его центре ты увидела трон, на котором сидела женщина... Твоя... мама?")
      pn()
      DaemonStart(_'королева')
      remove(_'сова')
      pic_set('30')
    end
  end;
  in_to = function(s)
    if not disabled(_'дверь') then
      return _'дверь'
    end
    return false
  end;
  n_to = function(s)
    if disabled(_'дверь') and visited(_'королева_диалог') then
      return _'голем'
    end
    if not disabled(_'дверь') then
      return _'дверь'
    end
    return false
  end;
  near = false;
  onexit = function(s, to)
    if to == _'королева_диалог' or to == _'badend2' or to == _'badend4' then
      return
    end
    if not s.near then
      if _'браслет':hasnt("worn") then
        if to == _'Зал_с_зеркалами' then
          p("Сейчас не лучшее время для прогулок.")
          return false
        end
        p("Поддавшись смутному интуитивному чувству, ты покидаешь тронный зал.")
        DaemonStop(_'королева')
        return
      end
      p("Ты нашла свою маму! Не время уходить!")
      return false
    end
    if fn_seen('голем') then
      if not visited(_'королева_диалог') then
        p("Ты пытаешься уйти из зала, но ледяной голем преграждает тебе путь.")
        return false
      end
    end
  end;
  ["out_to,e_to"] = 'ворота';
  ["s_to,d_to"] = '#лестница';
  u_to = function(s)
    if visited(_'комната') then
      return _'дверь'
    end
    return false
  end;
  before_Default = function(s, e, w)
    if not w then
      return false
    end
    if not (w == _'королева') and not (w == _'#трон') then
      return false
    end
    if e == 'Exam' or s.near then
      return false
    end
    if e == 'Walk' then
      return false
    end
    p("Сначала нужно подойти к трону.")
  end;
  obj = {
    'королева';
    'ворота';

    obj {
      -"трон|кресло";
      nam = "#трон";
      description = "Великолепный трон сделан, как и всё вокруг, из льда. Высокая прямая спинка украшена причудливыми узорами.";
      ["before_Enter,Climb"] = function(s, w, wh)
        if fn_seen('королева') then
          p("Трон занят.")
        else
          p("Тебе не нужна власть. Тебе нужна мама.")
        end
      end;
      before_Walk = function(s, w, wh)
        if _'Тронный_зал'.near then
          return false
        end
        p("Ты бежишь к трону. Твоё сердце от радости выпрыгивает из груди. Но что-то странное ты замечаешь в облике матери.\nВ нерешительности ты останавливаешься в нескольких шагах от неё.")
        if _'браслет':hasnt("worn") then
          fn_daemonStop(_'королева')
          walk(_'badend2')
          return
        end
        _'Тронный_зал'.near = true
      end;
    }:attr 'scenery,supporter';

    Prop {
      -"узоры|спинка|колонны|стены";
    };

    door {
      -"деревянная дверь|дверь";
      nam = "дверь";
      description = function(s)
        p("Небольшая деревянная дверь. Странно, что она сделана не из льда.")
        return false
      end;
      door_to = function(s)
        if here() == _'комната' then
          return _'Тронный_зал'
        else
          return _'комната'
        end
      end;
    }:attr 'scenery':disable();

    obj {
