    end
    if w == _'#стена' and here() == _'комната' then
      move(s, w)
      p("Ты нашла в стене одинокий шуруп и повесила на него зеркало.")
      return
    end
    return false
  end;
  before_Search = function(s, w, wh)
    if here() == _'комната' and not _'сова2'.finside and not s.seen then
      _'сова2'.num = 0
      DaemonStart(_'сова2')
