    s.seen = true
    p("Вместо своего отражения, ты видишь в зеркале свою маму! {$fmt em|Настоящую} маму.")
    if where(s) == _'#стена' then
      p("Ты видишь в зеркале комнату. Все вещи в ней находятся на своих местах.")
